def schema_annotations(value):
    if isinstance(value, dict):
        return {("examples" if k == "example" else k): ([v] if k == "example" else schema_annotations(v)) for k, v in value.items()}
    if isinstance(value, list):
        return [schema_annotations(v) for v in value]
    return value


