def completion_schemas():
    result, variants = {}, []
    for p in DATA:
        for c in p["authored_children"]:
            if c["kind"] == "read":
                continue
            op = c["operation"]
            name = "F" + op[0].upper() + op[1:] + "CompletionResult"
            if op in COMPLETION_FIELDS:
                fs = fields_from(COMPLETION_FIELDS[op], response=True)
                props = {f["name"]: f["schema"] for f in fs}
                schema = obj(props, description="Successful local operation result; referenced documents/resources are purpose-authorized and retrieved through their scoped boundary. Provider acceptance remains distinct from fulfillment.")
                if "redirectMethod" in props:
                    props["redirectMethod"] = {"enum": ["GET", "POST"]}
                    props["formFields"] = {"type": "array", "maxItems": 32, "items": obj({"name": {"type": "string", "minLength": 1, "maxLength": 64}, "value": {"type": "string", "maxLength": 4096}}), "description": "Approved provider-profile fields only. GET uses an empty array. Values may be sensitive gateway tokens; never log or persist in browser storage."}
                    schema["required"].append("formFields")
                    schema["if"] = {"properties": {"redirectMethod": {"const": "GET"}}}
                    schema["then"] = {"properties": {"formFields": {"maxItems": 0}}}
                if "uploadMethod" in props:
                    props["uploadMethod"] = {"const": "PUT"}
                    props["requiredHeaders"] = obj({"Content-Type": ref("mimeType")}, description="Required exact signed upload header. All other provider-specific secret headers are carried only by an approved transport profile, never copied from caller input.")
                    schema["required"].append("requiredHeaders")
            else:
                schema = obj({"resourceId": ref("uuid"), "resourceVersion": ref("version"),
                              "localWorkflowStage": {"const": c["transition"].split(">")[1]},
                              "decisionRecordId": ref("uuid"), "recordedAt": ref("instant")},
                             description="This administrative/domain command's complete output is an audited resource revision and decision reference; it has no redirect, secret grant or additional external result. Canonical persistence states remain independently authoritative.")
            # Some business-negative results complete processing without a positive
            # external fact. These fields therefore use closed discriminated variants.
            special = {
                "requestIdentityVerification": ("verificationStatus", ["verified"], ["unverified", "review_required"], ["verificationId", "verificationStatus"]),
                "checkInstallmentEligibility": ("eligibilityStatus", ["eligible"], ["ineligible", "review_required"], ["eligibilityId", "eligibilityStatus"]),
                "verifyPaymentCallback": ("verificationStatus", ["verified"], ["pending", "failed", "external_outcome_unknown"], ["attemptId", "verificationStatus"]),
                "decideClaimAssessment": ("decision", ["approve"], ["reject", "request_evidence"], ["assessmentId", "decisionId", "decision"]),
            }
            if op in special:
                discriminator, positive, negative, minimal = special[op]
                positive_schema = dict(schema)
                positive_schema["properties"] = dict(schema["properties"])
                positive_schema["properties"][discriminator] = {"enum": positive}
                neg_props = {k: schema["properties"][k] for k in minimal}
                neg_props[discriminator] = {"enum": negative}
                schema = {"oneOf": [positive_schema, obj(neg_props)], "discriminator": {"propertyName": discriminator}}
            result[name] = schema
            variants.append(obj({"operationId": {"const": op}, "result": {"$ref": "#/components/schemas/" + name}}, description="Result available only to the initiating principal or explicitly authorized delegate with current resource/property grants."))
    result["FCommandCompletion"] = {"oneOf": variants, "discriminator": {"propertyName": "operationId"},
        "description": "Closed operation-specific result union. Embed only when PendingCommand.status=succeeded. Unknown/rejected/pending/running commands must not carry fictitious completion. Reauthorize at each retrieval; secret-bearing URLs are short-lived and must never be cached or logged."}
    return result


def projection_schema(op, props):
    if op in PROJECTION_VARIANTS:
        discriminator, common, variants = PROJECTION_VARIANTS[op]
        cases = []
        for value, extra in variants.items():
            keys = (common + " " + extra).split()
            fields = {k: props[k] for k in keys}
            fields[discriminator] = {"type": "string", "const": value}
            cases.append(obj(fields, keys, "Closed " + value + " projection; apply property authority before serialization."))
        return {"oneOf": cases, "discriminator": {"propertyName": discriminator}}, cases[0]
    required = [k for k in props if k not in OPTIONAL_RESPONSE_FIELDS.get(op, set())]
    schema = obj(props, required, "Business identity/state and applicable facts are required. Optional fields denote genuinely absent facts, never fabricated defaults. Property authorization precedes serialization.")
    return schema, schema
for _op, _fields in list(READ_FIELDS.items()):
    READ_FIELDS[_op] = re.sub(r"(nonCashPoints|memberCount|qualifiedLeadCount|committedSaleCount|durationMs|queueAgeMs):version", r"\1:count", _fields)

