 child("versionAssistedProposal", "Proposal revisions and insurer negotiation", "inquiryId:uuid;carrierId:uuid;termsDocumentId:uuid;validUntil:instant", "assigned>proposal_draft", "Capture insurer-authored terms, covered risks, exclusions, price components and validity in immutable proposal versions; restrict negotiation notes to the authorized account team.", "Missing insurer evidence or changed risk marks the draft unapproved; customer-facing screens never show internal negotiation notes."),
